CREATE TABLE f_permits (id TEXT PRIMARY KEY, company_id TEXT, period_date TEXT, new_date TEXT, first_published_at TEXT, state TEXT, category TEXT, industry TEXT, jp INTEGER, unc INTEGER, size TEXT, amount REAL, category_rank INTEGER, ord INTEGER NOT NULL, is_sample INTEGER NOT NULL DEFAULT 0, card TEXT NOT NULL);
CREATE INDEX ix_f_permits_1_a ON f_permits (unc, new_date);
CREATE INDEX ix_f_permits_2_a ON f_permits (state, unc, new_date);
CREATE INDEX ix_f_permits_3_a ON f_permits (company_id);
CREATE TABLE f_ucc (id TEXT PRIMARY KEY, company_id TEXT, period_date TEXT, new_date TEXT, first_published_at TEXT, state TEXT, industry TEXT, jp INTEGER, noise INTEGER, idx INTEGER, candidate INTEGER, copy_status TEXT, candidate_score REAL, ord INTEGER NOT NULL, is_sample INTEGER NOT NULL DEFAULT 0, card TEXT NOT NULL);
CREATE INDEX ix_f_ucc_1_a ON f_ucc (noise, period_date);
CREATE INDEX ix_f_ucc_2_a ON f_ucc (state, noise, period_date);
CREATE INDEX ix_f_ucc_3_a ON f_ucc (company_id);
CREATE TABLE f_subsidies (id TEXT PRIMARY KEY, company_id TEXT, period_date TEXT, new_date TEXT, first_published_at TEXT, state TEXT, layer TEXT, category TEXT, industry TEXT, size TEXT, jp INTEGER, mfg INTEGER, amount REAL, ord INTEGER NOT NULL, capex INTEGER, is_sample INTEGER NOT NULL DEFAULT 0, card TEXT NOT NULL);
CREATE INDEX ix_f_subsidies_1_a ON f_subsidies (capex, amount);
CREATE INDEX ix_f_subsidies_2_a ON f_subsidies (capex, period_date);
CREATE INDEX ix_f_subsidies_3_a ON f_subsidies (company_id);
CREATE TABLE f_hiring (id TEXT PRIMARY KEY, company_id TEXT, period_date TEXT, new_date TEXT, first_published_at TEXT, state TEXT, industry TEXT, size TEXT, jp INTEGER, cross INTEGER, ord INTEGER NOT NULL, open_mfg INTEGER, types INTEGER, is_sample INTEGER NOT NULL DEFAULT 0, card TEXT NOT NULL);
CREATE INDEX ix_f_hiring_1_a ON f_hiring (ord);
CREATE INDEX ix_f_hiring_2_a ON f_hiring (state, ord);
CREATE INDEX ix_f_hiring_3_a ON f_hiring (company_id);
CREATE TABLE f_news (id TEXT PRIMARY KEY, company_id TEXT, period_date TEXT, new_date TEXT, first_published_at TEXT, state TEXT, relevance REAL, ord INTEGER NOT NULL, is_sample INTEGER NOT NULL DEFAULT 0, card TEXT NOT NULL);
CREATE INDEX ix_f_news_1_a ON f_news (period_date);
CREATE INDEX ix_f_news_2_a ON f_news (company_id);
CREATE TABLE f_permits_detail (parent_id TEXT NOT NULL, id TEXT NOT NULL, permit_no TEXT, permit_type TEXT, record_date TEXT, applied_date TEXT, value_usd REAL, gc_name TEXT, applicant_name TEXT, description TEXT, source_id TEXT, PRIMARY KEY (parent_id, id));
CREATE INDEX ix_f_permits_detail_1_a ON f_permits_detail (parent_id);
CREATE TABLE f_tag (face TEXT, dim TEXT, value TEXT, id TEXT, PRIMARY KEY (face, dim, value, id));
CREATE TABLE f_count (face TEXT, key TEXT, period TEXT, n INTEGER, PRIMARY KEY (face, key, period));
CREATE TABLE f_meta (face TEXT PRIMARY KEY, generated_at TEXT, synced_at TEXT, n_total INTEGER, meta TEXT);
CREATE TABLE company (id TEXT PRIMARY KEY, name TEXT, state TEXT, city TEXT, entity_type TEXT, website TEXT, header TEXT);
CREATE TABLE identity_map (old_id TEXT, new_id TEXT, kind TEXT, status TEXT, valid_from TEXT, valid_to TEXT);
CREATE TABLE c_item (company_id TEXT NOT NULL, face TEXT NOT NULL, ord INTEGER NOT NULL, id TEXT, src_face TEXT, item TEXT NOT NULL, PRIMARY KEY (company_id, face, ord));
CREATE VIRTUAL TABLE company_fts USING fts5(id UNINDEXED, name, tokenize='trigram');
